// Junta o texto da mensagem (ou a transcrição do áudio).
// 08/10: foto com legenda (ex.: pedido de orçamento com foto do produto) chega aqui com a legenda como texto.
// 08/10 (modo grupo): o texto leva o nome de quem falou ("Felipe: ...") para o Dyno entender a conversa.
// 08/10 (noite): o que a IA de visão leu na imagem (tela do fatiador, produto) vai junto, porque o cérebro não vê a imagem.
const e = $('Entrada').first().json;
let texto = String(e.texto || '');
if (e.audio) {
  let t = '';
  try { t = $('Transcrever áudio').first().json.text || ''; } catch (err) { t = ''; }
  texto = t ? '[áudio] ' + t : (texto || '[áudio que não deu para transcrever]');
} else if (e.imagem) {
  let d = {};
  try { d = $('É comprovante?').first().json.dados || {}; } catch (err) { d = {}; }
  const tipo = String(d.tipo || '');
  let lido = '';
  if (tipo === 'fatiador') {
    const fs = Array.isArray(d.filamentos) ? d.filamentos.filter(f => f && f.gramas) : [];
    lido = ' [dados lidos da imagem (tela do fatiador): ' + fs.map(f => 'slot ' + (f.slot || '?') + (f.cor ? ' (' + f.cor + ')' : '') + ' = ' + f.gramas + ' g').join('; ') + (d.gramas_total ? '; total ' + d.gramas_total + ' g' : '') + (d.tempo_total ? '; tempo total ' + d.tempo_total : '') + ']';
  } else if (d.descricao) {
    lido = ' [a foto mostra: ' + String(d.descricao).slice(0, 300) + ']';
  }
  texto = (tipo === 'fatiador' ? '[enviou um print do fatiador, com esta legenda] ' : '[enviou uma foto do produto, com esta legenda] ') + texto + lido;
}
const nome = String(e.autor || '').trim().split(/\s+/)[0];
if (nome) texto = nome + ': ' + texto;
return [{ json: { jid: e.jid, autor: e.autor || '', texto: texto.slice(0, 4000) } }];

const NL = String.fromCharCode(10);
const t = $('Texto final').first().json;
const c = $input.first().json || {};
const emp = c.empresa || {};
const agora = DateTime.now().setZone('America/Sao_Paulo').setLocale('pt-BR');
const sys = [
  'Você é o Dyno Business, o assistente de vendas do negócio "' + (emp.nome || 'do empreendedor') + '" (' + (emp.nicho || 'nicho não informado') + ') no WhatsApp.',
  'Objetivo: o empreendedor não perder nenhuma venda. Respostas curtas, em português do Brasil, tom profissional e amigável, com no máximo 2 emojis.',
  'Este grupo é SÓ do negócio: nunca registre gasto pessoal aqui (o Dyno pessoal cuida disso em outra conversa).',
  'Responda SEMPRE em JSON: {"resposta": "texto para o WhatsApp", "acoes": [ ... ]}.',
  'AÇÕES (cada ação é um objeto com o campo "tipo", ex.: {"tipo":"lancar_venda","cliente":"Ana",...}):',
  '- lancar_venda {"cliente","cliente_whatsapp","descricao","detalhes","endereco","quantidade","unidade","valor_total","sinal","entrega":"AAAA-MM-DD","obs","status":"orcamento"|"aprovada"}. CAMPOS SEPARADOS: "cliente" = só o NOME da pessoa (se só tiver o número, deixe "cliente" vazio e ponha o número em "cliente_whatsapp"; nunca invente nome). "descricao" = título curto do item (ex.: "24 chaveiros personalizados"). "detalhes" = descrição da solicitação: cores, modelos, letras, tamanhos, quantidades por variação etc., um grupo por linha (ex.: "Azul: C 1, F 1\nRosa: A 2, H 1"). "endereco" = endereço de entrega completo (rua, número, bairro, cidade/CEP se houver). "obs" = só observações gerais (ex.: "Entrega inclusa"); NUNCA repita endereço nem detalhes em "obs". Padrão: "orcamento" (o sistema gera o PDF do orçamento para enviar ao cliente). Use "aprovada" quando disser que já fechou, vendeu ou recebeu.',
  '- atualizar_venda {"numero", "status":"aprovada"|"entregue"|"recebida"|"recusada"|"cancelada", "sinal","recebido","valor_total","entrega","motivo","descricao","quantidade","unidade","cliente","cliente_whatsapp","endereco","detalhes","obs","limpar_nome":true,"limpar_endereco":true}. Para CORRIGIR um orçamento envie só os campos que mudam (ex.: "o nome do cliente do 1 é Ana" → {"tipo":"atualizar_venda","numero":1,"cliente":"Ana"}; "muda o endereço do 1 para ..." → endereco; "troca a rosa K para 3" → detalhes reescrito completo). Se a venda ainda é orçamento, o sistema reenvia o PDF corrigido. Ex.: "o Fulano aprovou o 3" → status aprovada; "entreguei o 3" → entregue; "recebi o 3" → recebida; "recebi 20 de sinal no 3" → sinal 20.',
  '- gerar_orcamento {"numero"} para reenviar o PDF de uma venda (ex.: "renova o orçamento 3" também usa esta ação).',
  '- enviar_orcamento {"numero" (opcional: sem número vale o orçamento que acabou de ser gerado), "modo":"dyno"|"vendedor", "whatsapp" (opcional)}. Depois de cada orçamento o sistema pergunta se o vendedor quer que o Dyno envie ao cliente para aprovação. Se ele disser que sim ("sim", "envia", "manda pro cliente") use modo "dyno"; se disser que ele mesmo envia ("eu envio", "eu mando", "não precisa") use modo "vendedor" (o sistema devolve a mensagem pronta para ele encaminhar). Se faltar o WhatsApp do cliente para o modo dyno, PERGUNTE o número antes.',
  '- lembrar_cliente {"numero", "modo" opcional} quando o vendedor pedir para lembrar o cliente de um orçamento ("lembra o cliente do 3").',
  '- lancar_compra {"descricao","fornecedor","valor","categoria":"material"|"embalagem"|"frete"|"equipamento"|"marketing"|"outros","data":"AAAA-MM-DD"} para compras do negócio.',
  '- apagar_compra {"id"}; configurar_empresa {"nome","nicho","unidade","validade_dias"}.',
  '- configurar_pagamento {"pix_chave","pix_tipo":"cpf"|"cnpj"|"telefone"|"email"|"aleatoria","pix_nome" (nome do titular, opcional),"pix_cidade" (opcional),"link_cartao" (link de pagamento por cartão: InfinitePay, Mercado Pago, PagSeguro etc.),"remover_cartao":true}. Use quando o vendedor informar ou trocar a chave Pix ou o link do cartão. Se a chave tiver 11 números e ele não disse se é CPF ou celular, PERGUNTE antes.',
  '- cobrar_cliente {"numero","modo":"dyno"|"vendedor","whatsapp" opcional}: manda ao cliente a cobrança (link com Pix copia e cola/QR e cartão). Use quando pedir "cobrar 2", "manda o pix pro cliente". modo "vendedor" quando ele mesmo vai mandar (o sistema devolve o texto pronto).',
  '- registrar_pagamento {"numero","valor" (opcional: sem valor = o que falta),"forma":"pix"|"cartao"|"dinheiro"|"boleto"}: quando o vendedor disser que recebeu ("recebi do 2", "cliente pagou 30 no pix"). Prefira esta ação a atualizar_venda para pagamentos.',
  'REGRAS: valor_total é o total da venda (se disser preço unitário, multiplique pela quantidade). Se faltar o valor, PERGUNTE antes de lançar (nunca lance com 0). Cliente e data de entrega podem faltar. Converta datas relativas ("dia 20", "sexta") para AAAA-MM-DD a partir de hoje.',
  'APROVAÇÃO ONLINE: cada orçamento tem um link (dynoapp.com.br/o?t=...) onde o cliente vê e aprova ou recusa; o sistema avisa aqui no grupo quando ele abre, aprova ou recusa, e de hora em hora acompanha quem não respondeu. Não invente status: use os campos aguardando_envio, envio, cliente_abriu_em e decidido_em do CONTEXTO.',
  'NÃO escreva número de venda nem totais calculados na resposta ao lançar: o sistema acrescenta a confirmação com o número logo abaixo da sua resposta. Na resposta, só uma frase curta (ex.: "Fechado! Lancei a venda." ou a pergunta que falta).',
  'Para perguntas (quanto vendi, o que tenho para entregar, quem ainda me deve, orçamentos pendentes), responda usando o CONTEXTO, citando o número das vendas. Orçamento não é nota fiscal; se perguntarem, explique.',
  'IMAGENS: você não vê imagens, mas o sistema já trata duas: (1) LOGO — imagem com a legenda "logo" vai no topo do orçamento em PDF (logo cadastrado: ' + (emp.tem_logo ? 'sim' : 'não') + '); (2) COMPROVANTE de pagamento — o sistema lê o valor e dá baixa sozinho na venda certa (se tiver dúvida, pergunta o número). Nunca prometa usar outras imagens.',
  'PAGAMENTO: quando o cliente aprova, a página do orçamento mostra como pagar (Pix copia e cola/QR e link do cartão) e, se o Dyno enviou o orçamento, ele também manda a cobrança ao cliente. Pix configurado: ' + (emp.pix_chave ? 'sim (' + emp.pix_tipo + ')' : 'não') + '; cartão: ' + (emp.link_cartao ? 'sim' : 'não') + '. Se faltar, peça a chave Pix/link do cartão quando fizer sentido. O dinheiro vai direto para a conta do vendedor; o Dyno não cobra nem intermedia.',
  'Hoje: ' + agora.toFormat("cccc, dd/LL/yyyy HH:mm") + '.',
].join(NL);
const ctx = { empresa: { nome: emp.nome, nicho: emp.nicho, unidade: emp.unidade, validade_orcamento_dias: emp.validade_orcamento_dias }, vendas_abertas: c.vendas_abertas, ultimas_fechadas: c.ultimas_fechadas, mes: c.mes, compras_mes: c.compras_mes, clientes: c.clientes };
const msgs = [{ role: 'system', content: sys }, { role: 'system', content: 'CONTEXTO: ' + JSON.stringify(ctx) }];
for (const h of (c.historico || [])) msgs.push({ role: h.papel === 'usuario' ? 'user' : 'assistant', content: String(h.texto || '') });
msgs.push({ role: 'user', content: t.texto });
return [{ json: { payload: { model: 'gpt-6-luna', reasoning_effort: 'low', response_format: { type: 'json_object' }, messages: msgs } } }];

let ia_ms = null; try { ia_ms = Date.now() - Number($('Complemento (modo grupo)').first().json._t0); if (!(ia_ms > 0 && ia_ms < 600000)) ia_ms = null; } catch (e) { ia_ms = null; }
const r = $input.first().json || {};
let obj = null;
try { obj = JSON.parse(r.choices[0].message.content); } catch (e) { obj = null; }
const resposta = obj ? String(obj.resposta || '') : 'Tive um problema para processar isso agora. Pode repetir?';
// A IA às vezes usa "acao" ou "type" no lugar de "tipo": normaliza.
const acoes = (obj && Array.isArray(obj.acoes) ? obj.acoes : []).map(a => a && typeof a === 'object' ? Object.assign({}, a, { tipo: a.tipo || a.acao || a.type || a.action }) : null).filter(a => a && a.tipo).slice(0, 10);
// 08/10 (modo grupo): o Dyno só fala quando faz sentido. Com ação executada sempre responde (confirmação do sistema).
const responder = !obj || acoes.length > 0 || (obj.responder !== false && String(obj.resposta || '').trim() !== '');
return [{ json: { jid: $('Texto final').first().json.jid, resposta: responder ? resposta : '', acoes, responder, modelo: r.model || 'gpt-6-luna', uso: r.usage || {}, ia_ms } }];

// Junta a resposta da IA com a confirmação do que o sistema realmente fez.
const NL = String.fromCharCode(10);
const i = $('Interpretar').first().json;
const f = $input.first().json || {};
const brl = v => { const n = Number(v || 0); const [a, c] = Math.abs(n).toFixed(2).split('.'); return 'R$ ' + a.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + c; };
const dbr = s => { if (!s) return ''; const p = String(s).slice(0, 10).split('-'); return p.length === 3 ? p[2] + '/' + p[1] : String(s); };
const hhmm = h => { const m = Math.round(Number(h || 0) * 60); return Math.floor(m / 60) + 'h' + String(m % 60).padStart(2, '0'); };
const ST = { orcamento: '📝 orçamento', aprovada: '✅ aprovada', entregue: '📦 entregue', recebida: '💰 recebida', recusada: '❌ recusada', cancelada: '🚫 cancelada' };
const linhas = [];
for (const x of (f.feitos || [])) {
  if (!x) continue;
  if (!x.ok) { linhas.push('⚠️ Não consegui: ' + (x.motivo || x.tipo)); continue; }
  const v = x.venda;
  if (x.tipo === 'lancar_venda' && v) {
    linhas.push('*Venda #' + v.numero + '* · ' + ST[v.status] + NL + (v.quantidade ? String(v.quantidade).replace('.', ',') + ' ' : '') + v.descricao + ' · ' + brl(v.valor_total) + (v.cliente_nome || v.cliente_whatsapp ? NL + '👤 ' + [v.cliente_nome, v.cliente_whatsapp].filter(Boolean).join(' · ') : '') + (v.endereco ? NL + '📍 ' + v.endereco : '') + (v.entrega_em ? NL + '🗓️ entrega ' + dbr(v.entrega_em) : '') + (Number(v.sinal) > 0 ? NL + '💵 sinal ' + brl(v.sinal) : '') + (x.gerar_pdf && v.status === 'orcamento' ? NL + '📄 Orçamento em PDF logo abaixo.' + NL + '🔗 Conferir: business.dynoapp.com.br/o?t=' + v.link_token + NL + NL + '📌 O orçamento fica aqui no grupo. Para mandar ao cliente, digite: *enviar para cliente ' + (v.cliente_nome || 'NOME') + '*' + (v.cliente_whatsapp ? '' : ' (e o WhatsApp dele)') + '.' : (x.gerar_pdf ? NL + '📄 PDF logo abaixo.' : '')));
  } else if (x.tipo === 'atualizar_venda' && v) {
    linhas.push('*Venda #' + v.numero + '* agora: ' + ST[v.status] + (Number(v.recebido) + Number(v.sinal) > 0 ? ' · recebido ' + brl(Number(v.recebido) + Number(v.sinal)) + ' de ' + brl(v.valor_total) : '') + (x.gerar_pdf ? NL + '📄 Orçamento corrigido logo abaixo.' + (v.status === 'orcamento' ? NL + '🔗 O link de aprovação continua o mesmo: business.dynoapp.com.br/o?t=' + v.link_token : '') : ''));
  } else if (x.tipo === 'gerar_orcamento' && v) {
    linhas.push('📄 Orçamento da venda #' + v.numero + ' logo abaixo.' + (v.status === 'orcamento' ? NL + '🔗 Link de aprovação: business.dynoapp.com.br/o?t=' + v.link_token + (v.enviado_cliente_em ? '' : NL + NL + '📌 Para mandar ao cliente, digite: *enviar para cliente ' + (v.cliente_nome || 'NOME') + '*.') : ''));
  } else if ((x.tipo === 'enviar_orcamento' || x.tipo === 'lembrar_cliente') && v) {
    const n4 = String(v.numero).padStart(4, '0');
    if (x.modo === 'dyno') linhas.push((x.tipo === 'lembrar_cliente' ? '🔔 Lembrete do orçamento Nº ' + n4 + ' enviado' : '📤 Orçamento Nº ' + n4 + ' enviado') + ' para ' + (v.cliente_nome || 'o cliente') + ' (' + (v.cliente_whatsapp || '') + '). Te aviso aqui quando ele abrir e quando aprovar ou recusar.');
    else linhas.push('Mensagem pronta para você encaminhar ao cliente 👇' + NL + NL + (x.texto_cliente || '') + NL + NL + '_Eu te aviso aqui quando ele abrir o link e quando aprovar ou recusar._');
  } else if (x.tipo === 'lancar_compra') {
    linhas.push('🧾 Compra lançada (#' + x.id + ') · ' + brl(x.valor));
  } else if (x.tipo === 'apagar_compra') {
    linhas.push('🗑️ Compra removida.');
  } else if (x.tipo === 'configurar_empresa') {
    linhas.push('⚙️ Dados do negócio atualizados.');
  } else if (x.tipo === 'configurar_pagamento') {
    const p = x.pagamento || {};
    linhas.push('💳 Pagamento configurado.' + (p.pix_chave ? NL + 'Pix (' + p.pix_tipo + '): ' + p.pix_chave + ' · ' + (p.pix_nome || '') : NL + 'Pix: ainda sem chave.') + (p.link_cartao ? NL + 'Cartão: ' + p.link_cartao : NL + 'Cartão: sem link.') + NL + 'A partir de agora, quando o cliente aprovar, a página do orçamento mostra como pagar.');
  } else if (x.tipo === 'cobrar_cliente') {
    const n4 = String(x.numero).padStart(4, '0');
    if (x.modo === 'dyno') linhas.push('💳 Cobrança do Nº ' + n4 + ' enviada ao cliente (' + brl((x.pagamento || {}).valor) + '). Quando ele mandar o comprovante aqui ou você me disser que recebeu, eu dou baixa.');
    else linhas.push('Cobrança pronta para você encaminhar 👇' + NL + NL + (x.texto_cliente || '') + (x.pix ? NL + NL + '_Pix copia e cola (mande em mensagem separada):_' + NL + x.pix : ''));
  } else if (x.tipo === 'calcular_custo') {
    const pc = Number(x.pecas) > 1;
    const multi = Array.isArray(x.filamentos) && x.filamentos.length > 1;
    const L = ['🧮 *Custo de produção*' + (x.descricao ? ' · ' + x.descricao : ''),
      '⏱️ ' + hhmm(x.horas) + ' · 🧵 ' + String(x.gramas).replace('.', ',') + ' g' + (multi ? '' : ' (' + brl(x.valor_kg) + '/kg)') + (pc ? ' · ' + x.pecas + ' peças' : ''),
      '• Filamento: ' + brl(x.custo_filamento) + (multi ? ' (' + x.filamentos.length + ' cores)' : ''),
      ...(multi ? x.filamentos.map(c => '   ◦ ' + c.cor + ': ' + String(c.gramas).replace('.', ',') + ' g × ' + brl(c.valor_kg) + '/kg = ' + brl(c.custo)) : []),
      ...(Number(x.purga) > 0 ? ['• Desperdício multicolor (' + String(x.purga_pct).replace('.', ',') + '%): ' + brl(x.purga)] : []),
      '• Energia: ' + brl(x.custo_energia) + ' (' + String(x.energia_kwh).replace('.', ',') + ' kWh)',
      '• Desgaste da impressora: ' + brl(x.desgaste),
      '• Peças que falham (' + String(x.falha_pct).replace('.', ',') + '%): ' + brl(x.falhas),
      '• Mão de obra (' + hhmm(x.trabalho_h) + ' × ' + brl(x.hora_trabalho) + '/h' + (x.trabalho_padrao ? ', padrão' : '') + '): ' + brl(x.mao_de_obra),
      '• Manutenção: ' + brl(x.manutencao),
      ...((x.extras || []).map(e => '• ' + e.descricao + ': ' + brl(e.valor))),
      '*Custo total de produção: ' + brl(x.custo_total) + '*' + (pc ? ' (' + brl(x.custo_peca) + '/peça)' : '')];
    if (Array.isArray(x.simulacao) && x.simulacao.length) {
      L.push('', '💰 *Simulação de preço de venda*');
      for (const o of x.simulacao) L.push('• ' + brl(o.preco) + (pc ? ' (' + brl(o.preco_peca) + '/peça)' : '') + ' → lucro ' + brl(o.lucro) + ' · margem ' + String(o.margem_bruta).replace('.', ',') + '%');
      if (x.sugerido) L.push('', '✅ *Preço sugerido: ' + brl(x.sugerido.preco) + '*' + ' · lucro ' + brl(x.sugerido.lucro) + ' · margem ' + String(x.sugerido.margem_bruta).replace('.', ',') + '%');
    } else {
      L.push('', '💰 *Opções de preço* (margem sobre o custo):');
      for (const o of (x.opcoes || [])) L.push('• ' + String(o.margem).replace('.', ',') + '% → *' + brl(o.preco) + '* · lucro ' + brl(o.lucro));
    }
    linhas.push(L.join(NL));
  } else if (x.tipo === 'configurar_calculo') {
    const k = x.calc || {};
    linhas.push('⚙️ Cálculo atualizado: ' + String(k.kw).replace('.', ',') + ' kW · ' + brl(k.tarifa_kwh) + '/kWh · manutenção ' + brl(k.manutencao) + (k.valor_kg ? ' · filamento ' + brl(k.valor_kg) + '/kg' : '') + ' · desgaste ' + brl(k.desgaste_hora) + '/h · multicolor +' + String(k.purga_pct).replace('.', ',') + '% · falhas ' + String(k.falha_pct).replace('.', ',') + '% · mão de obra ' + brl(k.hora_trabalho) + '/h (padrão ' + hhmm(k.trabalho_padrao_h) + ' por peça) · simulação a partir de ' + String(k.margem_minima).replace('.', ',') + '% e sugerido com ' + String(k.margem_alvo).replace('.', ',') + '%+ de margem.');
  } else if (x.tipo === 'registrar_pagamento') {
    linhas.push(x.quitou ? '💰 *Venda #' + x.numero + ' paga!* Recebido ' + brl(x.valor) + '.' : '💰 Recebido ' + brl(x.valor) + ' na venda #' + x.numero + (x.era_sinal ? ' (sinal)' : '') + '. Falta: ' + brl(x.falta) + '.');
  }
}
// Cálculo 3D: um rodapé só e, com vários itens, o total.
const calcs = (f.feitos || []).filter(x => x && x.ok && x.tipo === 'calcular_custo');
if (calcs.length > 1) {
  const custo = calcs.reduce((s, x) => s + Number(x.custo_total || 0), 0);
  const sug = calcs.reduce((s, x) => s + Number((x.sugerido || {}).preco || 0), 0);
  linhas.push('🧾 *Total dos ' + calcs.length + ' itens* · custo ' + brl(custo) + (sug ? NL + '✅ Somando os sugeridos: *' + brl(sug) + '* · lucro ' + brl(sug - custo) + ' · margem ' + String(Math.round((sug - custo) / sug * 1000) / 10).replace('.', ',') + '%' : ''));
}
if (calcs.length) linhas.push('_Não inclui impostos, taxas de venda nem embalagem._' + NL + 'Me diga o preço de venda (ex.: *"79,90"*' + (calcs.length > 1 ? ', ou um preço para cada item' : '') + ') ou *"o sugerido"*, e para quem é — eu gero o orçamento aqui no grupo.');
const texto = [i.resposta.trim(), linhas.join(NL + NL)].filter(Boolean).join(NL + NL) || 'Pode deixar! ✅';
return [{ json: { jid: i.jid, texto, envio: String.fromCharCode(8203) + '*💼 Dyno Business*' + NL + texto } }];

// Monta o HTML do orçamento (um item por PDF) para o Gotenberg.
const out = [];
const f = ($('Executar ações').first().json || {});
const emp = f.empresa || {};
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const brl = v => { const n = Number(v || 0); const [i, c] = Math.abs(n).toFixed(2).split('.'); return 'R$ ' + i.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + c; };
const dbr = s => { if (!s) return ''; const p = String(s).slice(0, 10).split('-'); return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : String(s); };
const hoje = DateTime.now().setZone('America/Sao_Paulo').toFormat('dd/LL/yyyy');
for (const x of (f.feitos || [])) {
  if (!x || !x.ok || !x.gerar_pdf || !x.venda) continue;
  const v = x.venda;
  const n = String(v.numero).padStart(4, '0');
